            "text": "下一秒，照片自行消失，你立刻檢查相簿與垃圾桶，卻找不到任何刪除紀錄，其他照片全都完好無缺，只有與白髮孩子有關的內容不見了，你重新拿起畫紙，畫中那名沒有臉的孩子已經轉了回去，彷彿剛才的改變從未發生，桌面另一端，從育幼院帶回來的木製拼圖忽然輕輕動了一下，那塊畫著藍色窗戶的木片自行滑向畫紙，停在白髮孩子的手邊，緊接著，紙面上逐漸浮現一行新的字。",
