    "ch4_section_27": [
      {
        "type": "section",
        "title": "消失的時間"
      },
      {
        "type": "text",
        "pages": [
          {
            "text": "黎靖再次恢復意識時，已經變回紫貓，牠趴在客廳沙發上，尾巴不安地拍打椅墊，過了一會兒，牠重新化為人形，抬頭看向你。",
            "speaker": ""
          },
          {
            "text": "「我怎麼了？」",
            "speaker": "黎靖"
          },
          {
            "text": "「你不記得剛才發生的事？」",
            "speaker": "你"
          },
          {
            "text": "「剛才？」",
            "speaker": "黎靖"
          },
          {
            "text": "黎靖看向地上的原稿或碎片。",
            "speaker": ""
          },
          {
            "text": "「我只記得自己碰到它。」",
            "speaker": "黎靖"
          },
          {
            "text": "「然後呢？」",
            "speaker": "你"
          },
          {
            "text": "「沒有然後。」",
            "speaker": "黎靖"
          },
          {
            "text": "他停頓片刻。",
            "speaker": ""
          },
          {
            "text": "「等我再次有意識的時候，就已經在這裡了。」",
            "speaker": "黎靖"
          },
          {
            "text": "黎靖從口袋裡取出時間紀錄，紙上已經多了一行字。",
            "speaker": ""
          },
          {
            "text": "01：42——不要讓他繼續查。",
            "speaker": ""
          },
          {
            "text": "黎靖盯著那句話。",
            "speaker": ""
          },
          {
            "text": "「不是我寫的。」",
            "speaker": "黎靖"
          },
          {
            "text": "「我知道。」",
            "speaker": "黎靖"
          },
          {
            "text": "「是他？」",
            "speaker": "黎靖"
          },
          {
            "text": "「可能。」",
            "speaker": "你"
          },
          {
            "text": "黎靖抬頭看向你。",
            "speaker": ""
          },
          {
            "text": "「你學會了。」",
            "speaker": "黎靖"
          },
          {
            "text": "「什麼？」",
            "speaker": "你"
          },
          {
            "text": "「說可能。」",
            "speaker": "黎靖"
          },
          {
            "text": "即使在這種時候，他仍然有心情指出這件事，你一時不知道該不該感到欣慰。",
            "speaker": ""
          }
        ]
      },
      {
        "type": "jump",
        "target": "ch4_choice_28"
      }
    ],
