    "ch5_section_7": [
      {
        "type": "section",
        "title": "黑貓的記憶"
      },
      {
        "type": "text",
        "pages": [
          {
            "text": "當你碰觸項圈、死亡紀錄或合照時，動物醫院的牆面開始褪色，診療桌變成堆滿漫畫稿的書桌，運輸籠變成放著貓砂與飼料的角落，窗外也從漆黑深夜轉為陰雨午後，你站在蘇璟辰生前的工作室，粉色頭髮的青年趴在書桌上睡著了，他的臉依然被黑暗遮蔽，身旁散落著喝空的咖啡罐、藥袋與畫到一半的原稿。",
            "speaker": ""
          },
          {
            "text": "一隻黑貓蹲在桌角，牠用前腳推了推蘇璟辰的手，青年沒有反應，黑貓又推了一次，接著踩過原稿，直接趴到他的手臂上。",
            "speaker": ""
          },
          {
            "text": "「……重。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "蘇璟辰沒有睜眼，只將手掌覆在貓背上，黑貓發出低沉的呼嚕聲。",
            "speaker": ""
          },
          {
            "text": "「你今天吃藥了嗎？」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "黑貓沒有回答。",
            "speaker": ""
          },
          {
            "text": "「沒有吧。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "青年撐起身體，從桌角拿起藥袋，裡面應該放著他的藥，卻只剩被咬破的包裝，蘇璟辰沉默幾秒。",
            "speaker": ""
          },
          {
            "text": "「黎靖。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "黑貓抬起頭。",
            "speaker": ""
          },
          {
            "text": "「那不是貓零食。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "「喵。」",
            "speaker": "黑貓黎靖"
          },
          {
            "text": "「你還敢回答？」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "黑貓踩過他的手，跳到鍵盤上，畫面中的對話框立刻多出一整排沒有意義的字，蘇璟辰盯著螢幕。",
            "speaker": ""
          },
          {
            "text": "「很好。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "「下一話就讓你當反派。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "黑貓甩了一下尾巴，完全不在意，你第一次看見的，不是蘇璟辰受傷、反擊或死亡的記憶，只是他與一隻貓共同生活的普通午後。",
            "speaker": ""
          }
        ]
      },
      {
        "type": "jump",
        "target": "ch5_choice_8"
      }
    ],
