    "ch5_section_30": [
      {
        "type": "section",
        "title": "黑貓留下的東西"
      },
      {
        "type": "text",
        "pages": [
          {
            "text": "你和黎靖回到老宅走廊，原本的動物醫院已經消失，地面只留下黑貓生前使用的碗、舊項圈與一張日常漫畫稿。",
            "speaker": ""
          },
          {
            "text": "畫中，黑貓趴在蘇璟辰的原稿上，蘇璟辰用筆輕敲牠的尾巴。",
            "speaker": ""
          },
          {
            "text": "對白框裡寫著：",
            "speaker": ""
          },
          {
            "text": "「你再壓下去，今天就沒有罐頭。」",
            "speaker": "蘇璟辰"
          },
          {
            "text": "下一格，黑貓換了一張稿紙繼續睡，最後一格沒有對白，只畫著蘇璟辰將罐頭打開，黎靖看了很久。",
            "speaker": ""
          },
          {
            "text": "「他騙貓。」",
            "speaker": "黎靖"
          },
          {
            "text": "「你看起來並不意外。」",
            "speaker": "你"
          },
          {
            "text": "「他本來就會。」",
            "speaker": "黎靖"
          },
          {
            "text": "黎靖將日常稿收起，這是他恢復記憶後，第一次主動保留與蘇璟辰有關的東西，不是因為蘇璟辰要求，也不是因為你替他決定，只是他自己選擇留下。",
            "speaker": ""
          }
        ]
      },
      {
        "type": "jump",
        "target": "ch5_choice_31"
      }
    ],
