    "ch5_section_36": [
      {
        "type": "section",
        "title": "虛假的答案"
      },
      {
        "type": "text",
        "pages": [
          {
            "text": "返回玄關途中，黎靖忽然停下。",
            "speaker": ""
          },
          {
            "text": "前方牆面掛著一只從未出現過的文件袋，紙面已經泛黃，左上角印著醫院標誌，中央則寫著：",
            "speaker": ""
          },
          {
            "text": "蘇璟辰——精神科診斷資料",
            "speaker": ""
          },
          {
            "text": "你和黎靖對視。",
            "speaker": ""
          },
          {
            "text": "「剛才有這個嗎？」",
            "speaker": "你"
          },
          {
            "text": "「沒有。」",
            "speaker": "黎靖"
          },
          {
            "text": "你取下文件袋，裡面放著一份保存多年的病歷，頁面邊緣留下反覆翻閱造成的磨損，醫院章戳、病歷號碼與醫師簽名一應俱全，不像臨時製造的道具。",
            "speaker": ""
          },
          {
            "text": "第一頁的個人資料大多遭黑色方塊遮蔽。",
            "speaker": ""
          },
          {
            "text": "病歷號碼：SJH-1995-0830",
            "speaker": ""
          },
          {
            "text": "姓名：███",
            "speaker": ""
          },
          {
            "text": "性別／年齡：男／24歲",
            "speaker": ""
          },
          {
            "text": "出生日期：████年8月30日",
            "speaker": ""
          },
          {
            "text": "身高／體重：181cm／60 kg",
            "speaker": ""
          },
          {
            "text": "就診醫院：台北市立 ○○ 醫院 精神醫學科",
            "speaker": ""
          },
          {
            "text": "主治醫師：林建安 醫師",
            "speaker": ""
          },
          {
            "text": "初診日期：████年█月██日",
            "speaker": ""
          },
          {
            "text": "最近就診：████年█月██日",
            "speaker": ""
          },
          {
            "text": "姓名雖然被遮住，出生日期與病歷編號後方的數字卻能與蘇璟辰的早期資料互相對應。",
            "speaker": ""
          },
          {
            "text": "這確實是他的病歷。",
            "speaker": ""
          },
          {
            "text": "可是翻到主要診斷欄時，紙面上的墨色突然變得異常濃重。",
            "speaker": ""
          },
          {
            "text": "解離性身分疾患。",
            "speaker": ""
          },
          {
            "text": "次人格自稱「黎靖」。",
            "speaker": ""
          },
          {
            "text": "下方還列出記憶空白、身體控制權轉換、不同聲音與行為模式，甚至將黑貓記憶描述為「患者為了替次人格建立身分而產生的虛構敘事」。",
            "speaker": ""
          },
          {
            "text": "所有內容都能解釋眼前發生的異常。",
            "speaker": ""
          },
          {
            "text": "兩個黎靖、消失的時間、無法共享的記憶，以及蘇璟辰透過黎靖身體說話的現象，答案完整得近乎完美。",
            "speaker": ""
          },
          {
            "text": "也正因如此，顯得更加可疑。",
            "speaker": ""
          },
          {
            "text": "文件最下方寫著：",
            "speaker": ""
          },
          {
            "text": "黎靖並非獨立個體，只是蘇璟辰為承受創傷而形成的人格。",
            "speaker": ""
          },
          {
            "text": "黎靖讀完以後，長時間沒有說話。",
            "speaker": ""
          },
          {
            "text": "你注意到主要診斷欄的紙張比其他頁面更加厚重，黑色字跡底下似乎還壓著另一層內容，當頁面朝向燈光時，紙背隱約透出幾個無法完整辨認的字。",
            "speaker": ""
          },
          {
            "text": "焦慮……",
            "speaker": ""
          },
          {
            "text": "憂鬱……",
            "speaker": ""
          },
          {
            "text": "失眠……",
            "speaker": ""
          },
          {
            "text": "DID診斷可能不是整份病歷原本的內容，但病歷本身並非虛構。",
            "speaker": ""
          }
        ]
      },
      {
        "type": "jump",
        "target": "ch5_choice_37"
      }
    ],
